CREATE OR REPLACE FUNCTION public.used_car_preserve_delivery()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
 if (old.status='delivered' or exists(select 1 from public.customers c where c.interested_car_id=old.id and c.delivered))
 and (new.status is distinct from 'delivered' or (old.final_deal is not null and new.final_deal is null)) then
  raise exception 'DELIVERED_LOCKED: A delivered car cannot return to stock or have its deal cancelled.';
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.used_car_bonus_finance_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
 if tg_table_name='payments' then
  if (tg_op<>'INSERT' and old.type='campaign_bonus') or (tg_op<>'DELETE' and new.type='campaign_bonus') then
   if current_setting('app.used_car_bonus_posting',true) is distinct from '1' then raise exception 'BONUS_IMMUTABLE: Use the authorised bonus workflow.';end if;
  end if;
 else
  if (tg_op<>'INSERT' and old.source_type in ('campaign_bonus','campaign_bonus_paid')) or (tg_op<>'DELETE' and new.source_type in ('campaign_bonus','campaign_bonus_paid')) then
   if current_setting('app.used_car_bonus_posting',true) is distinct from '1' then raise exception 'BONUS_IMMUTABLE: Posted bonus entries require a separate adjustment.';end if;
  end if;
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end $function$

